    <div class="card-header-left">
      <h3><i class="bi bi-briefcase-fill"></i> Modération des Offres</h3>
      <p>Consultez l'ensemble des offres d'emploi actives et supprimez les annonces non conformes.</p>
    </div>
  </div>

  <div class="manage-card-premium">
    <div class="admin-search-bar">
      <input type="text" placeholder="Rechercher offre ou recruteur..." [(ngModel)]="searchTerm" />
    </div>
    <div class="table-wrapper-premium">
      
      <div *ngIf="isLoading" class="loading-box">
        <i class="bi bi-arrow-clockwise spinning"></i> Chargement des offres d'emploi...
      </div>

      <table *ngIf="!isLoading" class="jobs-table-premium">
        <thead>
          <tr>
            <th class="th-left-padding">Titre du poste / Recruteur</th>
            <th>Localisation</th>
            <th>Type de Contrat</th>
            <th class="th-center-align">Actions</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let job of filteredJobs" class="table-row-premium">
            <td class="job-company-cell">
              <span class="clickable-job-title" style="font-size: 14px !important; font-weight: 700;" (click)="openJobCard(job)">{{ job.title }}</span>
              <span class="company-sub-badge"><i class="bi bi-building"></i> {{ job.company_name || job.recruiter_name || 'Recruteur' }}</span>
            </td>
            <td class="date-text-cell-premium">
              <div class="date-container-premium">
                <i class="bi bi-geo-alt"></i>
                <span>{{ job.location }}</span>
              </div>
            </td>
            <td class="date-text-cell-premium">
              <div class="date-container-premium">
                <i class="bi bi-file-earmark-text"></i>
                <span>{{ job.contract_type }}</span>
              </div>
            </td>
            <td class="status-cell-premium">
              <button class="btn-action-delete" (click)="onDeleteJob(job.id)">
                <i class="bi bi-x-circle-fill"></i> Retirer
              </button>
            </td>
          </tr>
        </tbody>
      </table>

    </div>
  </div>

  <div *ngIf="showJobCard && selectedJob" class="admin-user-card-overlay" (click)="closeJobCard()">
    <div class="admin-user-card" (click)="$event.stopPropagation()">
      <button class="admin-user-card-close" (click)="closeJobCard()">×</button>
      <div class="admin-user-card-header">
        <div>
          <h4>{{ selectedJob.title }}</h4>
          <p class="admin-user-role">Détails du poste</p>
        </div>
        <span class="admin-badge" [ngClass]="selectedJob.is_verified_company ? 'badge-success' : 'badge-warning'">
          {{ selectedJob.is_verified_company ? 'Entreprise certifiée' : 'Entreprise non certifiée' }}
        </span>
      </div>
      <div class="admin-user-card-body">
        <div class="admin-user-field"><span>Recruteur</span><strong>{{ selectedJob.company_name || selectedJob.recruiter_name || '—' }}</strong></div>
        <div class="admin-user-field"><span>Localisation</span><strong>{{ selectedJob.location || '—' }}</strong></div>
        <div class="admin-user-field"><span>Type de contrat</span><strong>{{ selectedJob.contract_type || '—' }}</strong></div>
        <div class="admin-user-field"><span>Email recruteur</span><strong>{{ selectedJob.recruiter_email || '—' }}</strong></div>
        <div class="admin-user-field"><span>Téléphone recruteur</span><strong>{{ selectedJob.recruiter_phone || '—' }}</strong></div>
        <div class="admin-user-field"><span>Adresse recruteur</span><strong>{{ selectedJob.recruiter_address || '—' }}</strong></div>
      </div>
    </div>
  </div>
</div>
